contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public {
        (bool ok, ) = address(c).call(
            abi.encodeWithSignature(
                "setL1BlockValues(uint64,uint64,uint256,bytes32,uint64,bytes32,uint256,uint256)",
                _number,
                _timestamp,
                _basefee,
                _hash,
                _sequenceNumber,
                _batcherHash,
                _l1FeeOverhead,
                _l1FeeScalar
            )
        );
        assert(
            !ok ||
            (c.number() == _number &&
             c.timestamp() == _timestamp &&
             c.basefee() == _basefee &&
             c.hash() == _hash &&
             c.sequenceNumber() == _sequenceNumber &&
             c.batcherHash() == _batcherHash &&
             c.l1FeeOverhead() == _l1FeeOverhead &&
             c.l1FeeScalar() == _l1FeeScalar)
        );
    }
}

